// 요청 바디를 정리한다.
const body = $json.body ?? $json;
// 기본 입력을 추출한다.
const sessionId = body.session_id || `sess-${Date.now()}`;
const message = typeof body.message === "string" ? body.message : "";
const demo = Boolean(body.demo);
const overrides = body.overrides ?? null;
// 액션 페이로드를 파싱한다.
let actionPayload = null;
try {
  const parsed = JSON.parse(message);
  if (parsed && typeof parsed === "object") {
    actionPayload = parsed;
  }
} catch (e) {
  actionPayload = null;
}
// 결과를 반환한다.
return [{
  json: {
    session_id: sessionId,
    message,
    demo,
    overrides,
    action_payload: actionPayload,
  }
}];

// 단계 상태를 초기화한다.
function initStageStatus() {
  const stages = ["1-1","1-2","1-3","1-4","1-5","1-6","1-7","1-8"];
  const status = {};
  stages.forEach((stage) => {
    status[stage] = { done: false, dirty: true, updated_at: null };
  });
  return status;
}

// 세션 기본 상태를 만든다.
function initSessionState(sessionId) {
  return {
    session_id: sessionId,
    input_params: {
      temperature: null,
      voltage: null,
      size: null,
      capacity: null,
      chip_prod_id: null,
    },
    selections: {
      chip_type_ids: null,
      reference_lot_id: null,
    },
    configs: {
      top_k: 5,
      top_k_sort: "rank",
      core_match_params: [
        "active_powder_base",
        "active_powder_additives",
        "ldn_avr_value",
        "cast_dsgn_thk",
      ],
    },
    stage_status: initStageStatus(),
    stage_outputs: { tables: {}, charts: [], briefing_blocks: [] },
    stage_notes: {},
    raw_refs: {
      top_k_raw_id: null,
      defect_raw_id: null,
      stage_outputs_path: null,
      stage_outputs_saved_at: null,
    },
    pending_action: null,
    last_gap: null,
    last_explain_stage: null,
    history: [],
    user_prefs: { chart_type: "bar", language: "ko" },
    last_error: null,
  };
}

// 저장된 상태를 안전하게 병합한다.
function mergeState(baseState, storedState) {
  if (!storedState || typeof storedState !== "object") {
    return baseState;
  }
  const merged = { ...baseState };
  Object.entries(storedState).forEach(([key, value]) => {
    if (value && typeof value === "object" && !Array.isArray(value) && merged[key] && typeof merged[key] === "object") {
      merged[key] = { ...merged[key], ...value };
    } else {
      merged[key] = value;
    }
  });
  return merged;
}

// 세션 ID를 가져온다.
const sessionId = $node["Init Request"].json.session_id;
// DB 조회 결과를 가져온다.
const rows = $items("Load State");
let storedState = null;
if (rows.length) {
  const raw = rows[0].json.state;
  if (raw) {
    try {
      storedState = JSON.parse(raw);
    } catch (e) {
      storedState = null;
    }
  }
}
// 세션 상태를 병합한다.
const baseState = initSessionState(sessionId);
const sessionState = mergeState(baseState, storedState);
// 결과를 반환한다.
return [{ json: { session_state: sessionState } }];

// 액션 페이로드를 확인한다.
const actionPayload = $node["Init Request"].json.action_payload;
// LLM 응답을 가져온다.
const llmRaw = $json;
const llmBody = llmRaw.body ?? llmRaw;
const content = llmBody?.choices?.[0]?.message?.content ?? "";
let route = "";
try {
  const parsed = JSON.parse(content);
  route = parsed.route || "";
} catch (e) {
  route = content.trim();
}
// 액션 페이로드가 있으면 simulation으로 고정한다.
if (actionPayload) {
  route = "simulation";
}
// 값이 비었으면 casual로 보정한다.
if (route !== "simulation") {
  route = "casual";
}
// 결과를 반환한다.
return [{ json: { route } }];

// LLM 응답을 파싱한다.
const llmRaw = $json;
const llmBody = llmRaw.body ?? llmRaw;
const content = llmBody?.choices?.[0]?.message?.content ?? "";
const state = $node["Merge State"].json.session_state;
// 캐주얼 블록을 만든다.
const blocks = [{ type: "text", section: "casual", value: content }];
// 응답을 만든다.
const response = { route: "casual", blocks, tables: {}, charts: [] };
// 결과를 반환한다.
return [{ json: { response, session_state: state } }];

// 상태를 불러온다.
const state = $node["Merge State"].json.session_state;
// 단계 상태를 확인한다.
const stageStatus = state.stage_status || {};
const hasResults = Boolean(stageStatus["1-8"]?.done);
// 입력값 완성 여부를 확인한다.
const inputParams = state.input_params || {};
const hasInputComplete = [
  inputParams.temperature,
  inputParams.voltage,
  inputParams.size,
  inputParams.capacity,
].every((v) => Boolean(v));
// pending_action을 확인한다.
const pending = state.pending_action;
const pendingAction = pending && typeof pending === "object" ? pending.action : "none";
// 마지막 액션을 확인한다.
const history = state.history || [];
const lastAction = history.length ? history[history.length - 1].action : "none";
// 힌트를 만든다.
const hint = [
  "[STATE_HINT]",
  `- has_results: ${String(hasResults).toLowerCase()}`,
  `- has_input_complete: ${String(hasInputComplete).toLowerCase()}`,
  `- pending_action: ${pendingAction}`,
  `- last_action: ${lastAction}`,
].join("
");
// 사용자 메시지를 합친다.
const message = $node["Init Request"].json.message;
const commandMessage = `${hint}

[사용자 메시지]
${message}`;
// 결과를 반환한다.
return [{ json: { command_message: commandMessage } }];

// 액션 페이로드를 확인한다.
const actionPayload = $node["Init Request"].json.action_payload;
// LLM 응답을 가져온다.
const llmRaw = $json;
const llmBody = llmRaw.body ?? llmRaw;
const content = llmBody?.choices?.[0]?.message?.content ?? "";
let action = "run";
let targetStage = null;
try {
  const parsed = JSON.parse(content);
  action = parsed.action || action;
  targetStage = parsed.target_stage ?? parsed.targetStage ?? null;
} catch (e) {
  const text = content.trim();
  if (text.includes("reset")) action = "reset";
  if (text.includes("explain")) action = "explain_stage";
}
// 액션 페이로드가 있으면 run으로 고정한다.
if (actionPayload) {
  action = "run";
  targetStage = null;
}
// 결과를 반환한다.
return [{ json: { action, target_stage: targetStage } }];

// 세션 상태를 초기화한다.
const state = $node["Merge State"].json.session_state;
state.input_params = { temperature: null, voltage: null, size: null, capacity: null, chip_prod_id: null };
state.selections = { chip_type_ids: null, reference_lot_id: null };
state.stage_status = (() => {
  const stages = ["1-1","1-2","1-3","1-4","1-5","1-6","1-7","1-8"];
  const status = {};
  stages.forEach((stage) => {
    status[stage] = { done: false, dirty: true, updated_at: null };
  });
  return status;
})();
state.stage_outputs = { tables: {}, charts: [], briefing_blocks: [] };
state.stage_notes = {};
state.pending_action = null;
state.last_gap = null;
state.last_explain_stage = null;
state.history = state.history || [];
state.history.push({ action: "reset", payload: {}, at: new Date().toISOString() });
// 응답을 만든다.
const response = {
  route: "simulation",
  blocks: [
    { type: "text", section: "summary", value: "시뮬레이션 상태를 초기화했어. 새로 시작해줘." },
  ],
  tables: {},
  charts: [],
};
// 결과를 반환한다.
return [{ json: { response, session_state: state } }];

// 입력 파싱 결과를 준비한다.
function safeParse(content, fallback) {
  try {
    return JSON.parse(content);
  } catch (e) {
    return fallback;
  }
}

// 라벨 맵을 준비한다.
const labelMap = {
  temperature: "온도",
  voltage: "전압",
  size: "크기",
  capacity: "용량",
  chip_prod_id: "CHIP 기종",
};

// 세션 상태를 가져온다.
const state = $node["Merge State"].json.session_state;
const hadResults = Boolean(state.stage_status?.["1-8"]?.done);
// 액션 페이로드를 확인한다.
const actionPayload = $node["Init Request"].json.action_payload;
// InputAgent 응답을 파싱한다.
const inputRaw = $node["InputAgent"].json;
const inputBody = inputRaw.body ?? inputRaw;
const inputContent = inputBody?.choices?.[0]?.message?.content ?? "{}";
const inputParams = safeParse(inputContent, {});
// UpdateAgent 응답을 파싱한다.
const updateRaw = $node["UpdateAgent"].json;
const updateBody = updateRaw.body ?? updateRaw;
const updateContent = updateBody?.choices?.[0]?.message?.content ?? "{}";
const update = safeParse(updateContent, {});

// pending 선택을 적용한다.
if (actionPayload && actionPayload.action === "select_candidates") {
  const selection = actionPayload.selection || {};
  if (selection.chip_type_ids) {
    state.selections.chip_type_ids = selection.chip_type_ids;
  }
}

// 입력값을 병합한다.
Object.entries(inputParams || {}).forEach(([key, value]) => {
  if (value !== null && value !== "") {
    state.input_params[key] = value;
  }
});

// 업데이트 입력값을 병합한다.
if (update.input_params) {
  Object.entries(update.input_params).forEach(([key, value]) => {
    if (value !== null && value !== "") {
      state.input_params[key] = value;
    }
  });
}

// 선택값 업데이트를 반영한다.
if (update.selections) {
  Object.entries(update.selections).forEach(([key, value]) => {
    if (value !== null && value !== "") {
      state.selections[key] = value;
    }
  });
}

// 설정값을 반영한다.
if (update.configs) {
  Object.entries(update.configs).forEach(([key, value]) => {
    if (value !== null) {
      state.configs[key] = value;
    }
  });
}

// 사용자 설정을 반영한다.
if (update.user_prefs) {
  Object.entries(update.user_prefs).forEach(([key, value]) => {
    if (value !== null && value !== "") {
      state.user_prefs[key] = value;
    }
  });
}

// 누락 업데이트 필드를 계산한다.
let missingUpdate = Array.isArray(update.missing_fields) ? update.missing_fields : [];
if (!hadResults) {
  missingUpdate = [];
}

// chip_prod_id가 있으면 입력 누락을 비운다.
const hasChip = Boolean(state.input_params.chip_prod_id);
const requiredFields = ["temperature", "voltage", "size", "capacity"];
const missingFields = hasChip
  ? []
  : requiredFields.filter((key) => !state.input_params[key]);

// 누락 업데이트가 있으면 pending_action을 만든다.
let pendingAction = null;
let blocks = [];
let tables = {};
let charts = [];
let status = "continue";

if (missingUpdate.length) {
  pendingAction = {
    action: "update_input_params",
    target_stage: "1-1",
    missing_fields: missingUpdate,
    requested_at: new Date().toISOString(),
  };
  state.pending_action = pendingAction;
  state.history.push({ action: "update_input_pending", payload: { missing: missingUpdate }, at: new Date().toISOString() });
  const labels = missingUpdate.map((name) => labelMap[name] || name);
  blocks = [
    { type: "text", section: "summary", value: `다음 값을 알려줘: ${labels.join(", ")}` },
  ];
  status = "missing_update";
}

// 입력 누락이면 input_form을 만든다.
if (!missingUpdate.length && missingFields.length) {
  const fields = [];
  const leftKeys = ["temperature", "size", "capacity", "voltage"];
  const rightKeys = ["chip_prod_id"];
  leftKeys.forEach((key) => {
    const value = state.input_params[key] || "";
    const field = {
      key,
      label: labelMap[key] || key,
      type: "text",
      value,
      column: "left",
    };
    if (key === "temperature") {
      field.type = "select";
      field.options = ["A", "B", "D"];
      field.unit = "특성";
    } else if (key === "voltage") {
      field.type = "number";
      field.unit = "V";
    } else if (key === "size") {
      field.type = "select";
      field.options = ["1005", "1608", "2012", "3216"];
    } else if (key === "capacity") {
      field.type = "number";
      field.unit = "pF";
      field.unit_options = ["pF", "nF", "uF"];
    }
    fields.push(field);
  });
  rightKeys.forEach((key) => {
    fields.push({
      key,
      label: labelMap[key] || key,
      type: "text",
      value: state.input_params[key] || "",
      placeholder: "예: CL32Y106KCBNB",
      column: "right",
    });
  });
  blocks = [
    {
      type: "input_form",
      form_id: "mlcc_basic_params",
      title: "시뮬레이션 조건 입력",
      description: "4개 조건 또는 CHIP 기종 중 하나를 입력해주세요.",
      fields,
      submit_label: "시뮬레이션 시작",
      submitted: false,
    },
  ];
  status = "missing_input";
}

// 결과를 반환한다.
return [{
  json: {
    status,
    blocks,
    tables,
    charts,
    session_state: state,
  }
}];

// 공용 에러 문구를 반환한다.
function buildFallbackMessage() {
  return "처리 중 문제가 발생했어요. 잠시 후 다시 시도해주세요.";
}

// 데모 모드를 확인한다.
const demo = $node["Init Request"].json.demo;
const state = $node["Merge Update"].json.session_state;

try {
  // 기본 응답 컨테이너를 준비한다.
  let blocks = [];
  let tables = {};
  let charts = [];
  let stageNotes = {};

  // 입력 요약 표를 만든다.
  const inputRows = Object.entries(state.input_params || {}).map(([key, value]) => ({
    "항목": key,
    "값": value || "",
  }));

  if (demo) {
    // 데모 요약 메시지를 만든다.
    blocks = [
      { type: "text", section: "summary", value: "데모 모드로 시뮬레이션을 시작합니다. 필요한 입력을 확인 중입니다." },
      { type: "table_ref", table_key: "input_params_table" },
    ];
    tables = { input_params_table: inputRows };
  } else {
    // 프로덕션 로직은 DB 쿼리로 구현해야 한다.
    blocks = [
      { type: "text", section: "summary", value: "프로덕션 시뮬레이션 로직은 n8n DB 노드로 구현해야 합니다." },
      { type: "table_ref", table_key: "input_params_table" },
    ];
    tables = { input_params_table: inputRows };
  }

  // 결과를 저장한다.
  state.stage_outputs = { tables, charts, briefing_blocks: blocks };
  state.stage_notes = stageNotes;

  // 결과를 반환한다.
  return [{ json: { blocks, tables, charts, session_state: state } }];
} catch (error) {
  // 공용 에러 메시지를 반환한다.
  const message = buildFallbackMessage();
  state.last_error = { stage: null, message: String(error) };
  const blocks = [
    { type: "text", section: "summary", value: message },
  ];
  return [{ json: { blocks, tables: {}, charts: [], session_state: state } }];
}

// 입력에서 응답 데이터를 꺼낸다.
const route = $node["Parse Route"].json.route;
const payload = $json;
const response = {
  route,
  blocks: payload.blocks || [],
  tables: payload.tables || {},
  charts: payload.charts || [],
};
// 결과를 반환한다.
return [{ json: { response, session_state: payload.session_state } }];
